UPDATE lab_markers SET description = 'The total number of white blood cells. It rises with infection and inflammation and can fall with some medications.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_wbc' AND description = 'A count of white blood cells, often used as broad context for infection, inflammation, immune activity, or medication effects.';
UPDATE lab_markers SET description = 'The number of red blood cells, which carry oxygen around the body.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_rbc' AND description = 'A count of red blood cells, interpreted with hemoglobin, hematocrit, and red-cell indices.';
UPDATE lab_markers SET description = 'The protein in red blood cells that carries oxygen. A low level is the usual sign of anemia.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_hemoglobin' AND description = 'The oxygen-carrying protein in red blood cells, commonly interpreted with hematocrit and RBC count.';
UPDATE lab_markers SET description = 'The share of blood volume made up of red blood cells. It usually moves with hemoglobin and rises with dehydration.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_hematocrit' AND description = 'The percentage of blood volume made up by red blood cells, interpreted with hemoglobin and hydration context.';
UPDATE lab_markers SET description = 'The average size of red blood cells. Iron deficiency tends to make them smaller, and low B12 or folate tends to make them larger.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_mcv' AND description = 'A red-cell size index interpreted with hemoglobin, hematocrit, B12, folate, and iron status.';
UPDATE lab_markers SET description = 'The average amount of hemoglobin in each red blood cell. It usually tracks MCV.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_mch' AND description = 'A red-cell index interpreted with hemoglobin, MCV, and anemia context.';
UPDATE lab_markers SET description = 'How densely hemoglobin is packed inside red blood cells, on average. It is one of the more stable red-cell measures.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_mchc' AND description = 'A red-cell index interpreted with hemoglobin, MCV, and anemia context.';
UPDATE lab_markers SET description = 'How much red blood cells vary in size. It often rises early in iron, B12 or folate deficiency.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_rdw' AND description = 'A measure of red-cell size variation interpreted with anemia and nutrient context.';
UPDATE lab_markers SET description = 'The number of platelets, the cell fragments that help blood clot. Inflammation can raise it.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_platelets' AND description = 'A count of platelets, the blood cells involved in clotting and sometimes affected by inflammation or medications.';
UPDATE lab_markers SET description = 'The number of neutrophils, the most common white blood cells and the first to respond to bacterial infection.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_neutrophils_absolute' AND description = 'The absolute neutrophil count, interpreted with WBC, infection/inflammation context, and medication effects.';
UPDATE lab_markers SET description = 'The share of white blood cells that are neutrophils. The count is easier to compare between draws than the percentage.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_neutrophils_percent' AND description = 'The percentage of white blood cells that are neutrophils, interpreted with the total WBC and absolute neutrophil count when available.';
UPDATE lab_markers SET description = 'The number of lymphocytes, the white blood cells that make antibodies and fight viruses.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_lymphocytes_absolute' AND description = 'The absolute lymphocyte count, interpreted with WBC, immune context, and medication effects.';
UPDATE lab_markers SET description = 'The share of white blood cells that are lymphocytes. It moves whenever another cell type rises or falls.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_lymphocytes_percent' AND description = 'The percentage of white blood cells that are lymphocytes, interpreted with total WBC and clinical context.';
UPDATE lab_markers SET description = 'The number of monocytes, white blood cells that clear away debris and help fight infection.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_monocytes_absolute' AND description = 'The absolute monocyte count, interpreted with the rest of the CBC differential.';
UPDATE lab_markers SET description = 'The number of eosinophils, white blood cells that rise with allergies, asthma and some parasitic infections.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_eosinophils_absolute' AND description = 'The absolute eosinophil count, interpreted with allergy, asthma, inflammatory, medication, and infection context.';
UPDATE lab_markers SET description = 'The number of basophils, the rarest white blood cells, which take part in allergic reactions.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_basophils_absolute' AND description = 'The absolute basophil count, interpreted with the rest of the CBC differential.';
UPDATE lab_markers SET description = 'The number of young white blood cells released early from the bone marrow, often during infection, inflammation or pregnancy.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_immature_granulocytes_absolute' AND description = 'A CBC differential marker interpreted with infection, inflammation, marrow response, and lab context.';
UPDATE lab_markers SET description = 'The pituitary gland’s signal to the thyroid. It usually rises when the thyroid is underactive and falls when it is overactive.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_tsh' AND description = 'A pituitary signal used to assess thyroid-axis status, interpreted with free thyroid hormones and symptoms.';
UPDATE lab_markers SET description = 'The unbound form of thyroxine, the main hormone the thyroid makes. Usually read alongside TSH.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_free_t4' AND description = 'A circulating thyroid hormone marker interpreted with TSH, symptoms, medications, and timing.';
UPDATE lab_markers SET description = 'Triiodothyronine, the most active thyroid hormone, counting both the bound and unbound forms.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_t3_total' AND description = 'A thyroid hormone marker interpreted with TSH, free T4, medications, and symptoms.';
UPDATE lab_markers SET description = 'The body’s main stress hormone, measured in the morning when it is normally highest. The time of the draw matters a lot.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_cortisol_am' AND description = 'A cortisol measurement whose interpretation depends heavily on collection time, medication exposure, and clinical context.';
UPDATE lab_markers SET description = 'An adrenal hormone the body turns into testosterone and estrogen. Levels fall steadily with age.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_dhea_s' AND description = 'An adrenal androgen marker interpreted with age, sex, symptoms, and other hormone data.';
UPDATE lab_markers SET description = 'The main form of estrogen. Levels change through the menstrual cycle, with age and with hormone therapy.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_estradiol' AND description = 'A primary estrogen marker that varies by cycle stage, age, therapy, and assay context.';
UPDATE lab_markers SET description = 'A pituitary hormone that drives the ovaries and testes. It rises around menopause.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_fsh' AND description = 'A reproductive hormone interpreted with cycle stage, age, estradiol, and clinical context.';
UPDATE lab_markers SET description = 'All the testosterone in the blood, both bound to proteins and free. Levels are highest in the morning.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_testosterone_total' AND description = 'Total testosterone includes protein-bound and free hormone, interpreted with free testosterone, SHBG when available, timing, and therapy context.';
UPDATE lab_markers SET description = 'The part of testosterone not bound to proteins, which the body can use directly.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_testosterone_free' AND description = 'Free testosterone estimates the unbound fraction and is interpreted with total testosterone, SHBG when available, and symptoms.';
UPDATE lab_markers SET description = 'The hormone that moves sugar from the blood into cells. Most meaningful when measured fasting.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_insulin' AND description = 'A metabolic hormone marker interpreted with glucose, fasting status, HOMA-IR, and medication context.';
UPDATE lab_markers SET description = 'An estimate of insulin resistance, calculated from fasting glucose and fasting insulin.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_homa_ir' AND description = 'A calculated insulin-resistance estimate interpreted with fasting glucose and insulin.';
UPDATE lab_markers SET description = 'Immunoglobulin A, the antibody that protects the lining of the gut, airways and other mucous membranes.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_iga_total_serum' AND description = 'An immunoglobulin marker interpreted with immune, inflammatory, and clinical context.';
UPDATE lab_markers SET description = 'Immunoglobulin G, the most common antibody in the blood and the main source of long-term immunity.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_igg_total_serum' AND description = 'An immunoglobulin marker interpreted with immune, inflammatory, and clinical context.';
UPDATE lab_markers SET description = 'Immunoglobulin M, the first antibody the body makes when it meets a new infection.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_igm_total_serum' AND description = 'An immunoglobulin marker interpreted with immune, inflammatory, and clinical context.';
UPDATE lab_markers SET description = 'A protein the liver makes in response to inflammation. It rises and falls within days, so the trend says more than a single result.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_crp' AND description = 'A non-specific marker of systemic inflammation. It is most useful as a trend alongside symptoms, recent infections, injuries, and other inflammatory markers.';
UPDATE lab_markers SET description = 'How fast red blood cells settle in a tube, a broad sign of inflammation. It changes more slowly than CRP.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_esr' AND description = 'A broad inflammation marker that often moves more slowly than CRP. Trends can help contextualize chronic inflammatory activity but are not specific to one cause.';
UPDATE lab_markers SET description = 'A protein that rises mainly with bacterial infections, which helps tell them apart from viral ones.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_procalcitonin' AND description = 'An inflammatory/infection-context marker interpreted with symptoms, clinical setting, and other labs.';
UPDATE lab_markers SET description = 'The protein that stores iron, and the usual measure of iron reserves. Inflammation can raise it even when stores are low.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_ferritin' AND description = 'A marker of stored iron that can also rise with inflammation. Interpretation depends on iron studies, blood counts, inflammation, and clinical context.';
UPDATE lab_markers SET description = 'The iron circulating in the blood at the time of the draw. It swings through the day and after meals or supplements.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_iron_serum' AND description = 'An iron-study marker interpreted with ferritin, TIBC, transferrin saturation, inflammation, and supplementation.';
UPDATE lab_markers SET description = 'How much iron the blood’s transport protein could carry. It tends to rise when iron stores are low.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_tibc' AND description = 'An iron-study marker interpreted with serum iron, ferritin, and transferrin saturation.';
UPDATE lab_markers SET description = 'The share of the blood’s iron-carrying capacity in use, calculated from serum iron and TIBC.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_transferrin_saturation' AND description = 'An iron-study percentage interpreted with serum iron, TIBC, ferritin, and inflammation context.';
UPDATE lab_markers SET description = 'All the cholesterol carried in the blood, including LDL and HDL.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_cholesterol_total' AND description = 'A lipid marker interpreted with LDL, HDL, triglycerides, medications, and cardiovascular risk context.';
UPDATE lab_markers SET description = 'Often called bad cholesterol, because it can build up in artery walls. It is the main target of cholesterol-lowering treatment.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_ldl' AND description = 'A lipid marker interpreted with cardiovascular risk, treatment context, and the rest of the lipid panel.';
UPDATE lab_markers SET description = 'Often called good cholesterol, because it carries cholesterol away from the arteries to the liver.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_hdl' AND description = 'A lipid marker interpreted with the broader lipid panel and cardiovascular risk context.';
UPDATE lab_markers SET description = 'The main form of fat in the blood. It rises after meals, so it is usually measured fasting.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_triglycerides' AND description = 'A lipid marker affected by fasting status, diet, metabolic health, medications, and genetics.';
UPDATE lab_markers SET description = 'Total cholesterol minus HDL: the cholesterol in every particle that can build up in arteries.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_non_hdl_cholesterol' AND description = 'A calculated lipid marker interpreted with LDL, HDL, triglycerides, and risk context.';
UPDATE lab_markers SET description = 'Cholesterol carried in very-low-density lipoproteins, usually estimated from triglycerides.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_vldl_cholesterol' AND description = 'A lipid marker often interpreted with triglycerides and the broader lipid panel.';
UPDATE lab_markers SET description = 'Total cholesterol divided by HDL, which combines the two into one number.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_cholesterol_hdl_ratio' AND description = 'A calculated lipid ratio interpreted with the broader lipid panel and risk context.';
UPDATE lab_markers SET description = 'The amount of sugar in the blood at the time of the draw. Whether it was taken fasting matters a lot.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_glucose' AND description = 'Blood glucose reflects current blood sugar and depends strongly on fasting status, meals, medications, and timing.';
UPDATE lab_markers SET description = 'Average blood sugar over the past two to three months, measured from the sugar attached to hemoglobin.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_hba1c' AND description = 'A marker of average blood sugar exposure over roughly the prior few months, interpreted with glucose and red-cell context.';
UPDATE lab_markers SET description = 'A waste product from muscle that the kidneys filter out. More muscle means a higher normal level.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_creatinine' AND description = 'A kidney-function marker used with eGFR and other metabolic-panel values; muscle mass and hydration can affect interpretation.';
UPDATE lab_markers SET description = 'An estimate of how well the kidneys filter blood, calculated from creatinine and age.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_egfr' AND description = 'An estimated kidney filtration measure usually calculated from creatinine and demographic inputs.';
UPDATE lab_markers SET description = 'A waste product from breaking down protein, filtered out by the kidneys. It rises with dehydration and high-protein diets.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_bun' AND description = 'A kidney and protein-metabolism marker interpreted with creatinine, hydration, diet, and clinical context.';
UPDATE lab_markers SET description = 'The main electrolyte controlling the balance of water in the body.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_sodium' AND description = 'An electrolyte interpreted with hydration, kidney function, medications, and other electrolytes.';
UPDATE lab_markers SET description = 'An electrolyte that keeps the heart and muscles working. A slow or difficult blood draw can falsely raise it.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_potassium' AND description = 'An electrolyte affected by kidney function, medications, hydration, and sample handling.';
UPDATE lab_markers SET description = 'An electrolyte that moves with sodium to balance fluids and the blood’s acid level.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_chloride' AND description = 'An electrolyte often interpreted with sodium, potassium, bicarbonate, and hydration context.';
UPDATE lab_markers SET description = 'Mostly bicarbonate, which keeps the blood’s acid balance steady.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_carbon_dioxide' AND description = 'A metabolic-panel marker often used as a proxy for bicarbonate/acid-base context.';
UPDATE lab_markers SET description = 'The main mineral in bone, also needed by nerves and muscles. Much of it is carried by albumin, so the two are read together.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_calcium' AND description = 'An electrolyte/mineral marker interpreted with albumin, kidney function, vitamin D, and clinical context.';
UPDATE lab_markers SET description = 'All the protein in the blood, mainly albumin and globulins.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_protein_total' AND description = 'A metabolic-panel protein measure interpreted with albumin, globulin, hydration, and immune context.';
UPDATE lab_markers SET description = 'The main protein in blood, made by the liver. It keeps fluid inside blood vessels and carries hormones and drugs.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_albumin' AND description = 'A blood protein commonly interpreted with the comprehensive metabolic panel and overall clinical context.';
UPDATE lab_markers SET description = 'A group of blood proteins that includes antibodies, usually calculated as total protein minus albumin.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_globulin' AND description = 'A calculated protein fraction interpreted with albumin, total protein, and immune context.';
UPDATE lab_markers SET description = 'Albumin divided by globulin, the two main groups of blood proteins.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_albumin_globulin_ratio' AND description = 'A calculated ratio interpreted with albumin, globulin, and total protein.';
UPDATE lab_markers SET description = 'A liver enzyme that rises when liver cells are irritated, including by alcohol, some medications and fatty liver.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_alt' AND description = 'A liver enzyme that can rise with liver irritation, medications, alcohol, metabolic changes, or muscle injury.';
UPDATE lab_markers SET description = 'An enzyme found in the liver, heart and muscles. Hard exercise can raise it as well as liver irritation.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_ast' AND description = 'An enzyme found in liver and other tissues, interpreted with ALT and the broader metabolic panel.';
UPDATE lab_markers SET description = 'An enzyme from the liver, bile ducts and bones. It is naturally higher in children, teenagers and pregnancy.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_alkaline_phosphatase' AND description = 'An enzyme interpreted with liver, biliary, bone, and broader metabolic-panel context.';
UPDATE lab_markers SET description = 'A yellow pigment left over from the normal breakdown of red blood cells, cleared by the liver.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_bilirubin_total' AND description = 'A liver and bile-processing marker interpreted with liver enzymes and clinical context.';
UPDATE lab_markers SET description = 'A by-product of making energy without enough oxygen. It rises with hard exercise and serious illness.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_lactate' AND description = 'A metabolic marker interpreted with acute clinical context, perfusion, exercise, and collection conditions.';
UPDATE lab_markers SET description = 'The standard test of vitamin D status. It changes with sun exposure, season and supplements.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_vitamin_d_25_oh' AND description = 'The usual blood marker for vitamin D status, interpreted with supplementation, sun exposure, season, and clinician targets.';
UPDATE lab_markers SET description = 'A vitamin needed for red blood cells and nerves. Diet, some medications and absorption problems can lower it.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_vitamin_b12' AND description = 'A nutrient marker interpreted with diet, supplementation, blood counts, symptoms, and related markers when available.';
UPDATE lab_markers SET description = 'A B vitamin needed to make red blood cells and DNA. Recent diet and supplements change it quickly.', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_folic_acid' AND description = 'A nutrient marker interpreted with diet, supplementation, blood counts, B12, and clinical context.';

UPDATE lab_markers SET default_units = 'ug/dL', updated_at = '2026-11-22T00:00:00Z' WHERE id = 'mk_tibc' AND default_units = 'mcg/dL';
